from itertools import permutations

def solve():
    people = ['Blake', 'Casey', 'Harper', 'Morgan', 'Sawyer']
    colors = ['blue', 'green', 'orange', 'red', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
    drinks = ['cocoa', 'coffee', 'juice', 'milk', 'tea']
    hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

    for perm_people in permutations(people):
        for perm_colors in permutations(colors):
            for perm_pets in permutations(pets):
                for perm_drinks in permutations(drinks):
                    for perm_hobbies in permutations(hobbies):
                        houses = [
                            {
                                'person': perm_people[i],
                                'color': perm_colors[i],
                                'pet': perm_pets[i],
                                'drink': perm_drinks[i],
                                'hobby': perm_hobbies[i]
                            }
                            for i in range(5)
                        ]

                        if check_all_constraints(houses):
                            return houses
    return None

def check_all_constraints(houses):
    def get_idx(attr, value):
        for i, h in enumerate(houses):
            if h[attr] == value:
                return i
        return -1

    def adj(i, j):
        return abs(i - j) == 1

    def imm_left(i, j):
        return j - i == 1

    orange_idx = get_idx('color', 'orange')
    if houses[orange_idx]['hobby'] == 'painting':
        return False

    horse_idx = get_idx('pet', 'horse')
    if houses[horse_idx]['person'] == 'Blake':
        return False

    blue_idx = get_idx('color', 'blue')
    sawyer_idx = get_idx('person', 'Sawyer')
    if not imm_left(blue_idx, sawyer_idx):
        return False

    casey_idx = get_idx('person', 'Casey')
    hiking_idx = get_idx('hobby', 'hiking')
    if not adj(casey_idx, hiking_idx):
        return False

    baking_idx = get_idx('hobby', 'baking')
    tea_idx = get_idx('drink', 'tea')
    if not imm_left(baking_idx, tea_idx):
        return False

    dog_idx = get_idx('pet', 'dog')
    if not imm_left(baking_idx, dog_idx):
        return False

    rabbit_idx = get_idx('pet', 'rabbit')
    fencing_idx = get_idx('hobby', 'fencing')
    if not adj(rabbit_idx, fencing_idx):
        return False

    if not adj(tea_idx, horse_idx):
        return False

    bird_idx = get_idx('pet', 'bird')
    if not adj(casey_idx, bird_idx):
        return False

    red_idx = get_idx('color', 'red')
    if not adj(red_idx, rabbit_idx):
        return False

    cocoa_idx = get_idx('drink', 'cocoa')
    if not adj(cocoa_idx, orange_idx):
        return False

    yellow_idx = get_idx('color', 'yellow')
    rowing_idx = get_idx('hobby', 'rowing')
    if yellow_idx != rowing_idx:
        return False

    harper_idx = get_idx('person', 'Harper')
    if bird_idx != harper_idx:
        return False

    if houses[sawyer_idx]['drink'] != 'juice':
        return False

    painting_idx = get_idx('hobby', 'painting')
    if not imm_left(blue_idx, painting_idx):
        return False

    if houses[bird_idx]['drink'] != 'milk':
        return False

    return True

solution = solve()
if solution:
    for h in solution:
        if h['pet'] == 'bird':
            print(f"ANSWER: {h['person']}")
            break
